css:
:root {
  --primary: #76f7ff;
  --primary-hover: #48c8f2;
  --bg: #040510;
  --bg-alt: #0a0f1f;
  --card-bg: rgba(12, 18, 37, 0.94);
  --text: #e8f7ff;
  --text-secondary: #9ad0ff;
  --border: #20304d;
  --magenta: #ff7cf3;
  --violet: #a77bff;
  --teal: #48ffd7;
  --grid: rgba(118, 247, 255, 0.12);
  --shadow-neon: 0 12px 40px rgba(10, 199, 255, 0.25);
}

body {
  background: radial-gradient(circle at 12% 18%, rgba(255, 124, 243, 0.12), transparent 40%),
              radial-gradient(circle at 88% 6%, rgba(118, 247, 255, 0.16), transparent 35%),
              linear-gradient(145deg, #050715 0%, #050a1c 45%, #041224 100%);
  color: var(--text);
  background-attachment: fixed;
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(0deg, transparent 95%, rgba(118,247,255,0.08) 95%),
                    linear-gradient(90deg, transparent 95%, rgba(118,247,255,0.08) 95%);
  background-size: 64px 64px;
  mix-blend-mode: screen;
  opacity: 0.5;
}

.header {
  background: linear-gradient(120deg, rgba(10, 199, 255, 0.35) 0%, rgba(255, 124, 243, 0.35) 50%, rgba(83, 119, 255, 0.35) 100%);
  border-bottom: 3px solid var(--primary);
  box-shadow: 0 18px 40px rgba(10,199,255,0.3), 0 6px 0 rgba(167, 123, 255, 0.4);
  backdrop-filter: blur(12px);
}

.brand {
  font-family: "Orbitron", "Saira", sans-serif;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: #76f7ff;
  text-shadow: 0 0 12px rgba(118,247,255,0.8), 0 0 28px rgba(255,124,243,0.7);
}

.toolbar .btn,
.toolbar button,
.toolbar input,
.toolbar select {
  border: 1px solid rgba(118,247,255,0.5);
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(12,22,42,0.9) 0%, rgba(27,44,75,0.9) 100%);
  color: var(--text);
  box-shadow: inset 0 0 0 1px rgba(10,199,255,0.2), 0 10px 30px rgba(0,0,0,0.35);
  transition: transform 0.15s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.toolbar button:hover {
  transform: translateY(-2px);
  border-color: var(--magenta);
  box-shadow: 0 12px 32px rgba(118,247,255,0.25), 0 0 0 2px rgba(255,124,243,0.25);
}

.card {
  background: var(--card-bg);
  border: 1px solid rgba(118,247,255,0.35);
  border-radius: 18px;
  box-shadow: var(--shadow-neon);
  position: relative;
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.18s ease;
}

.card::before {
  content: "";
  position: absolute;
  inset: -30% 10% 40% -30%;
  background: radial-gradient(circle, rgba(118,247,255,0.28) 0%, transparent 55%);
  filter: blur(6px);
}

.card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,124,243,0.1) 0%, rgba(118,247,255,0.1) 50%, rgba(83,119,255,0.1) 100%);
  mix-blend-mode: screen;
  opacity: 0.6;
}

.card:hover {
  transform: translateY(-6px) scale(1.01);
  border-color: rgba(255,124,243,0.6);
  box-shadow: 0 20px 50px rgba(10,199,255,0.35), 0 0 0 3px rgba(255,124,243,0.35);
}

.card .card-title {
  color: #f9fbff;
  text-shadow: 0 0 10px rgba(118,247,255,0.45);
  font-weight: 800;
  letter-spacing: 0.04em;
}

.card .card-body {
  color: var(--text-secondary);
  line-height: 1.75;
}

.card .tag,
.card .label {
  background: linear-gradient(90deg, rgba(118,247,255,0.9) 0%, rgba(255,124,243,0.9) 100%);
  color: #051024;
  border: 1px solid rgba(10,199,255,0.6);
  border-radius: 999px;
  box-shadow: 0 0 18px rgba(118,247,255,0.45), 0 0 26px rgba(255,124,243,0.35);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.sidebar,
.panel,
.modal,
.popover {
  background: rgba(5, 10, 28, 0.82);
  border: 1px solid rgba(118,247,255,0.28);
  box-shadow: 0 18px 38px rgba(0,0,0,0.6);
  backdrop-filter: blur(10px) saturate(130%);
}

.list-item,
.menu-item,
.dropdown-item {
  background: rgba(11, 20, 44, 0.85);
  border-radius: 12px;
  border: 1px solid rgba(167, 123, 255, 0.3);
  transition: background 0.18s ease, transform 0.18s ease;
}

.list-item:hover,
.menu-item:hover,
.dropdown-item:hover {
  background: rgba(13, 25, 55, 0.9);
  transform: translateX(6px);
  box-shadow: 0 10px 24px rgba(0,0,0,0.45);
}

.progress,
.timeline::before,
.board::before {
  background: linear-gradient(90deg, rgba(118,247,255,0.35), rgba(255,124,243,0.28), rgba(83,119,255,0.35));
}

.floating-ribbon {
  background: linear-gradient(120deg, #76f7ff 0%, #ff7cf3 50%, #5377ff 100%);
  color: #031020;
  box-shadow: 0 18px 40px rgba(10,199,255,0.35);
}
